import unittest

class Behavior(unittest.TestCase):
    def test_contract(self):
        from endpoints import authority
        for host, port, expected in [('2001:db8::7',8080,'[2001:db8::7]:8080'),
                                     ('::1',443,'[::1]:443'), ('::',1,'[::]:1'),
                                     ('2001:DB8::A',65535,'[2001:DB8::A]:65535'),
                                     ('192.0.2.7',80,'192.0.2.7:80'),
                                     ('printer.local',9100,'printer.local:9100')]:
            with self.subTest(host=host):
                self.assertEqual(authority(host, port), expected)

if __name__ == "__main__":
    unittest.main()

